WITH recent_payments AS (SELECT * FROM payments WHERE method IN ('promptpay', 'card', 'cash')), method_summary AS (SELECT method, DATE_TRUNC('MONTH', paid_at) AS paid_month, MAX(amount) - MIN(amount) AS amount_range FROM recent_payments GROUP BY method, DATE_TRUNC('MONTH', paid_at)) SELECT method, paid_month, amount_range FROM method_summary WHERE amount_range > 23 ORDER BY method DESC
